    63→    }
    64→    
    65→    deinit {
    66→        sessionVerificationController.setDelegate(delegate: nil)
    67→    }
    68→    
    69→    let actions = PassthroughSubject<SessionVerificationControllerProxyAction, Never>()
    70→    
    71→    func acknowledgeVerificationRequest(details: SessionVerificationRequestDetails) async -> Result<Void, SessionVerificationControllerProxyError> {
    72→        MXLog.info("Acknowledging verification request")
    73→        
    74→        do {
    75→            try await sessionVerificationController.acknowledgeVerificationRequest(senderId: details.senderProfile.userID, flowId: details.flowID)
    76→            return .success(())
    77→        } catch {
    78→            MXLog.error("Failed requesting session verification with error: \(error)")
    79→            return .failure(.failedAcknowledgingVerificationRequest)
    80→        }
    81→    }
    82→    
    83→    func acceptVerificationRequest() async -> Result<Void, SessionVerificationControllerProxyError> {
    84→        MXLog.info("Accepting verification request")
    85→        
    86→        do {
    87→            try await sessionVerificationController.acceptVerificationRequest()
    88→            return .success(())
    89→        } catch {
    90→            MXLog.error("Failed requesting session verification with error: \(error)")
    91→            return .failure(.failedAcceptingVerificationRequest)
    92→        }
    93→    }
    94→        
    95→    func requestDeviceVerification() async -> Result<Void, SessionVerificationControllerProxyError> {
    96→        MXLog.info("Requesting device verification")
    97→        
    98→        do {
    99→            try await sessionVerificationController.requestDeviceVerification()
   100→            return .success(())
   101→        } catch {
   102→            MXLog.error("Failed requesting device verification with error: \(error)")
   103→            return .failure(.failedRequestingVerification)
   104→        }
   105→    }
   106→    
   107→    func requestUserVerification(_ userID: String) async -> Result<Void, SessionVerificationControllerProxyError> {
   108→        MXLog.info("Requesting user verification")
   109→        
   110→        do {
   111→            try await sessionVerificationController.requestUserVerification(userId: userID)
   112→            return .success(())
   113→        } catch {
   114→            MXLog.error("Failed requesting verification for user \(userID) with error: \(error)")
   115→            return .failure(.failedRequestingVerification)
   116→        }
   117→    }
   118→    
   119→    func startSasVerification() async -> Result<Void, SessionVerificationControllerProxyError> {
   120→        MXLog.info("Starting SAS verification")
   121→        
   122→        do {
   123→            try await sessionVerificationController.startSasVerification()
   124→            return .success(())
   125→        } catch {
   126→            MXLog.error("Failed starting SAS verification with error: \(error)")
   127→            return .failure(.failedStartingSasVerification)
   128→        }
   129→    }
   130→    
   131→    func approveVerification() async -> Result<Void, SessionVerificationControllerProxyError> {
   132→        MXLog.info("Approving verification")
   133→        
   134→        do {
   135→            try await sessionVerificationController.approveVerification()
   136→            return .success(())
   137→        } catch {
   138→            MXLog.error("Failed approving verification with error: \(error)")
   139→            return .failure(.failedApprovingVerification)
   140→        }
   141→    }
   142→    
   143→    func declineVerification() async -> Result<Void, SessionVerificationControllerProxyError> {
   144→        MXLog.info("Declining verification")
   145→        
   146→        do {
   147→            try await sessionVerificationController.declineVerification()
   148→            return .success(())
   149→        } catch {
   150→            MXLog.error("Failed declining verification with error: \(error)")
   151→            return .failure(.failedDecliningVerification)
   152→        }
   153→    }
   154→    
   155→    func cancelVerification() async -> Result<Void, SessionVerificationControllerProxyError> {
   156→        MXLog.info("Cancelling verification")
   157→        
   158→        do {
   159→            try await sessionVerificationController.cancelVerification()
   160→            return .success(())
   161→        } catch {
   162→            MXLog.error("Failed cancelling verification with error: \(error)")
   163→            return .failure(.failedCancellingVerification)
   164→        }
   165→    }
   166→    
   167→    // MARK: - Private
   168→    
   169→    fileprivate func didReceiveVerificationRequest(details: MatrixRustSDK.SessionVerificationRequestDetails) {
   170→        MXLog.info("Received verification request \(details)")
   171→        
   172→        let details = SessionVerificationRequestDetails(senderProfile: UserProfileProxy(sdkUserProfile: details.senderProfile),
   173→                                                        flowID: details.flowId,
   174→                                                        deviceID: details.deviceId,
   175→                                                        deviceDisplayName: details.deviceDisplayName,
   176→                                                        firstSeenDate: Date(timeIntervalSince1970: TimeInterval(details.firstSeenTimestamp / 1000)))
   177→        
   178→        actions.send(.receivedVerificationRequest(details: details))
   179→    }
   180→    
   181→    fileprivate func didAcceptVerificationRequest() {
   182→        MXLog.info("Accepted verification request")
   183→        
   184→        actions.send(.acceptedVerificationRequest)
   185→    }
   186→    
   187→    fileprivate func didStartSasVerification() {
   188→        MXLog.info("Started SAS verification")
   189→        
   190→        actions.send(.startedSasVerification)
   191→    }
   192→    
   193→    fileprivate func didReceiveData(_ data: [MatrixRustSDK.SessionVerificationEmoji]) {
   194→        MXLog.info("Received verification data")
